 grammar:[['The number of awards ___ fallen.',['have','has','are'],1,'The subject is “the number”, which is singular.'],['Support is available ___ students with caring responsibilities.',['for','of','by'],0,'“Available for” identifies eligible recipients.'],['___ financial support, some students could not enrol.',['Without','Unless','Although'],0,'“Without” takes a noun phrase.'],['The results do not necessarily ___ causation.',['establish','establishes','establishing'],0,'After “do not”, use the base verb.'],['Choose the strongest concession.',['Although fewer awards were offered, each recipient received more adequate support.','Fewer awards. More support. So good.','All smaller programmes are better.'],0,'This acknowledges the trade-off without overgeneralising.'],['Applications rose from 100 to 150: choose the accurate description.',['An increase of 50 per cent','An increase of 150 per cent','A decrease of 50 per cent'],0,'The increase is 50 divided by the original 100, or 50%.']],
