 vocab:[['adaptive','changing in response to information about a user','identical for every person'],['retain','keep information or ability over time','finish an exercise rapidly'],['transfer','apply learning in a different context','repeat the same answer mechanically'],['relevance','how closely something relates to the question or purpose','the number of words in a paragraph'],['autonomy','the ability to make one’s own decisions','being required to follow every instruction'],['interruption','a break in an ongoing activity','a permanent improvement'],['objective','based on defined evidence or criteria','always complete and without limitations'],['synthesise','combine information into a coherent whole','copy a single source unchanged']],
 grammar:[['Each learner ___ a different exercise.',['receive','receives','receiving'],1,'“Each learner” is singular.'],['Explanations helped learners ___ their errors.',['understand','understood','understanding'],0,'“Help someone understand” uses the base verb.'],['The study lasted ___ twelve weeks.',['for','since','during of'],0,'“For” introduces a duration.'],['___ completing tasks quickly, learners should reflect on mistakes.',['Rather than','Despite of','Because'],0,'“Rather than” introduces the contrasted -ing phrase.'],['Choose the evidence-based conclusion.',['The platform may support vocabulary retention, but the non-random sample limits generalisation.','The platform guarantees success for everyone.','No digital tool can help any learner.'],0,'This claim is qualified and explicitly recognises the sample limitation.'],['Choose the accurate phrasing.',['Fewer errors and less time','Less errors and fewer time','Fewest time and lesser errors'],0,'Errors are countable; time is uncountable.']],
 task1:{title:'Completion of online course activities',kind:'bar comparison',unit:'Percentage of enrolled learners',columns:['Activity','2020','2024'],rows:[['Video lessons',85,90],['Quizzes',70,82],['Writing assignments',35,55],['Peer discussions',20,48]],overview:'Overall, completion increased for every activity, with video lessons remaining the most frequently completed. Peer discussions showed the largest rise in percentage points.',pitfalls:'These are completion rates for separate activities, so each year does not total 100%. Peer discussions rose 28 percentage points, while writing rose 20.'},
